from __future__ import annotations

from html import escape
from urllib.parse import quote

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse, RedirectResponse

from .branding import PRODUCT_FULL_NAME
from .tenant_storage import project_path

router = APIRouter()


@router.get("/song-editor/{project_name}/performance", response_class=HTMLResponse, include_in_schema=False)
def performance_to_song_portal(project_name: str, request: Request):
    member = getattr(request.state, "member", None)
    if member is None:
        return RedirectResponse(
            f"/signin?next=/song-editor/{quote(project_name, safe='')}/performance",
            status_code=303,
        )
    try:
        project_path(project_name, must_exist=True)
    except Exception:
        return HTMLResponse("<h1>Project not found</h1>", status_code=404)
    encoded = quote(project_name, safe="")
    brand = escape(PRODUCT_FULL_NAME)
    html = r"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='robots' content='noindex,nofollow'><title>Performance → Song — __BRAND__</title><style>
:root{--bg:#03040a;--panel:#0d1120;--line:#ffffff20;--gold:#e9c86f;--violet:#9a6dff;--cyan:#55dcff;--green:#72e0a8;--red:#ff8fa5;--muted:#bac1d4;--text:#fff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 9% 0,#42186d66,transparent 28%),radial-gradient(circle at 94% 1%,#16437466,transparent 25%),#03040a;color:#fff;font-family:Inter,ui-sans-serif,system-ui,sans-serif;min-height:100vh}a{color:inherit;text-decoration:none}.wrap{width:min(1350px,calc(100% - 28px));margin:auto}.nav{position:sticky;top:0;z-index:10;background:#05060bef;border-bottom:1px solid var(--line);backdrop-filter:blur(18px)}.navin{min-height:70px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.brand{font-weight:950}.brand small{display:block;color:var(--gold);font-size:.65rem;letter-spacing:.09em;text-transform:uppercase}.btn,button{border:1px solid var(--line);border-radius:11px;padding:9px 12px;background:#ffffff08;color:#fff;font:inherit;font-weight:850;cursor:pointer}.primary{border:0!important;background:linear-gradient(115deg,var(--gold),var(--violet))!important;color:#150d1c!important}.good{border-color:#72e0a855!important;color:var(--green)!important}.hero{padding:38px 0 18px}.eyebrow{font-size:.7rem;letter-spacing:.16em;text-transform:uppercase;color:var(--gold);font-weight:950}h1{font-size:clamp(2.5rem,6vw,5rem);line-height:.94;letter-spacing:-.05em;margin:.14em 0 .2em}.lead,.muted{color:var(--muted);line-height:1.6}.grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:12px;padding-bottom:55px}.card{border:1px solid var(--line);border-radius:19px;background:linear-gradient(145deg,#111628ed,#090c18f2);padding:16px;margin:10px 0}.guide{border:1px solid var(--line);border-radius:14px;padding:12px;margin:8px 0;background:#ffffff05;cursor:pointer}.guide.active{border-color:var(--gold);box-shadow:0 0 0 2px #e9c86f18 inset}.pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:4px 8px;font-size:.7rem;margin:2px}.pill.good{color:var(--green)}.form{display:grid;gap:9px}.row{display:grid;grid-template-columns:1fr 1fr;gap:9px}.field,textarea,select{width:100%;border:1px solid var(--line);border-radius:11px;padding:10px;background:#060912;color:#fff;font:inherit;outline:none}textarea{min-height:90px;resize:vertical}.checks{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.check{border:1px solid var(--line);border-radius:11px;padding:8px;background:#ffffff04}.check input{width:auto}.notice{display:none;border:1px solid var(--line);border-radius:12px;padding:11px;margin:10px 0}.notice.show{display:block}.notice.bad{border-color:#ff8fa555;color:#ffd8df}.result{border-left:4px solid var(--green);padding:13px;background:#72e0a50a;border-radius:13px;overflow-wrap:anywhere}.empty{padding:22px;text-align:center;color:var(--muted);border:1px dashed #ffffff2d;border-radius:14px}@media(max-width:900px){.grid{grid-template-columns:1fr}.checks{grid-template-columns:1fr 1fr}}@media(max-width:600px){.row,.checks{grid-template-columns:1fr}}
</style></head><body><nav class='nav'><div class='wrap navin'><a class='brand' href='/song-editor/__PROJECT__'>__BRAND__<small>Performance → editable mastered song</small></a><div><a class='btn' href='/song-editor/__PROJECT__/audition'>Audition edits</a> <a class='btn' href='/song-editor/__PROJECT__'>Song DNA</a> <a class='btn' href='/daw'>DAW</a></div></div></nav><main class='wrap'><section class='hero'><div class='eyebrow'>Play it, tap it, hum it — Aura builds around you</div><h1>Turn your musical gesture into a real production.</h1><p class='lead'>Choose a rights-confirmed performance guide. A real instrument can remain audible as the preserved anchor. A tapped rhythm, beatbox or hum can act as generation conditioning while staying muted in the release mix. The generated result remains multitrack/editable and is mastered through the release-quality gate.</p><div id='notice' class='notice'></div></section><section class='grid'><aside><div class='card'><div class='eyebrow'>Performance guides</div><h2>Choose the source</h2><div id='guides'><div class='empty'>Loading…</div></div><a class='btn' href='/song-editor/__PROJECT__/audition'>Upload another guide</a></div></aside><div><div class='card'><div class='eyebrow'>Generation setup</div><h2 id='selectedTitle'>Select a performance guide.</h2><form id='form' class='form'><div class='row'><div><label>Genre</label><input class='field' name='genre' value='pop'></div><div><label>Mood</label><input class='field' name='mood' value='uplifting'></div></div><div class='row'><div><label>Instrument upload role</label><select name='source_role'><option value='other'>Auto / other</option><option>guitar</option><option>bass</option><option>drums</option><option value='keyboard'>keyboard / piano</option><option>synth</option><option>strings</option><option>brass</option><option>woodwinds</option><option>percussion</option><option>vocals</option></select></div><div><label>Output</label><select name='output_mode'><option value='multitrack'>Editable multitrack</option><option value='complete_mix'>Complete mix</option></select></div></div><label>Real-audio instruments Aura should create</label><div class='checks'>__ROLES__</div><div class='row'><label class='check'><input type='checkbox' name='include_lead_vocal'> Add lead vocal</label><label class='check'><input type='checkbox' name='include_backing_vocals'> Add backing vocals</label></div><label>Lyrics (optional)</label><textarea name='lyrics' placeholder='Paste complete lyrics, or leave blank if the selected workflow should remain instrumental.'></textarea><label>Additional direction</label><textarea name='extra_direction' placeholder='Example: warm live drums, emotional acoustic guitar, build hard into the final chorus'></textarea><div class='row'><div><label>BPM override</label><input class='field' name='bpm' type='number' min='30' max='300' step='.1' placeholder='Use detected BPM'></div><div><label>Key override</label><input class='field' name='key' placeholder='Use detected key hint'></div></div><div class='row'><div><label>Meter</label><input class='field' name='meter' value='4/4'></div><label class='check' style='align-self:end'><input type='checkbox' name='automix' checked> Aura AutoMix</label></div><button class='primary' type='submit'>Generate editable mastered production</button></form></div><div id='result'></div></div></section></main><script>
const PROJECT='__PROJECT__',$=id=>document.getElementById(id);let guides=[],selected=null;function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function notice(m,b=false){const n=$('notice');n.textContent=m;n.className='notice show'+(b?' bad':'');clearTimeout(window._n);window._n=setTimeout(()=>n.className='notice',7500)}async function req(url,opt={}){const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});let b={};try{b=await r.json()}catch(e){}if(!r.ok)throw new Error(b.detail||`Request failed (${r.status})`);return b}
async function load(){try{const d=await req(`/projects/${PROJECT}/performance-inputs`);guides=d.inputs||[];$('guides').innerHTML=guides.length?guides.slice().reverse().map(x=>`<div class="guide ${selected?.id===x.id?'active':''}" onclick="pick('${x.id}')"><div><b>${esc(x.label)}</b><span class="pill">${esc(x.kind)}</span>${x.status==='applied'?'<span class="pill good">applied</span>':''}</div><div class="muted">${esc(x.detected_bpm??'—')} BPM · key hint ${esc(x.pitch_class_hint??'—')} · ${x.midi_ref?'MIDI guide + real audio':'real audio guide'}</div><p class="muted">${esc(x.generation_context)}</p></div>`).join(''):'<div class="empty">No performance guides yet. Upload one from the Audition console.</div>';if(!selected&&guides.length)pick(guides[guides.length-1].id)}catch(e){notice(e.message,true)}}function pick(id){selected=guides.find(x=>x.id===id);$('selectedTitle').textContent=selected?`Build from: ${selected.label}`:'Select a performance guide.';load()}
$('form').addEventListener('submit',async e=>{e.preventDefault();if(!selected)return notice('Choose a performance guide first.',true);const fd=new FormData(e.target);const roles=[...document.querySelectorAll('input[name="roles"]:checked')].map(x=>x.value);const body={genre:fd.get('genre')||'pop',mood:fd.get('mood')||'uplifting',source_role:fd.get('source_role')||'other',roles,lyrics:fd.get('lyrics')||'',include_lead_vocal:fd.get('include_lead_vocal')==='on',include_backing_vocals:fd.get('include_backing_vocals')==='on',extra_direction:fd.get('extra_direction')||'',bpm:fd.get('bpm')?Number(fd.get('bpm')):null,key:fd.get('key')||null,meter:fd.get('meter')||'4/4',output_mode:fd.get('output_mode')||'multitrack',automix:fd.get('automix')==='on'};$('result').innerHTML='<div class="card"><p class="muted">Aura is generating real-audio parts, building the DAW session, mixing and mastering. This can take several minutes on a local GPU.</p></div>';notice('Generation started. Keep this page open for the current synchronous renderer path.');try{const d=await req(`/projects/${PROJECT}/performance-inputs/${encodeURIComponent(selected.id)}/generate`,{method:'POST',body:JSON.stringify(body)});$('result').innerHTML=`<div class="card result"><h2>Production generated.</h2><p><b>Master:</b> ${esc(d.master||d.output||'Created')}</p><p><b>Technical gate:</b> ${d.technical_gate_passed===false?'Failed':'Passed / renderer reported success'}</p><p class="muted">Perceptual listening review: ${d.perceptual_review_required===false?'not required':'required before claiming final release quality'}. Symbolic guide used as final audio: ${d.symbolic_guide_used_as_final_audio?'YES — investigate':'No'}.</p><div><a class="btn good" href='/song-editor/${PROJECT}/audition'>Audition Song DNA edits</a> <a class="btn" href='/daw'>Open DAW</a></div></div>`;notice('Editable production generated and returned from the mastering path.')}catch(err){$('result').innerHTML='';notice(err.message,true)}});load();
</script></body></html>"""
    roles = "".join(
        f"<label class='check'><input type='checkbox' name='roles' value='{role}' checked> {label}</label>"
        for role, label in [
            ("drums", "Drums"),
            ("bass", "Bass"),
            ("guitar", "Guitar"),
            ("keyboard", "Piano / Keys"),
            ("synth", "Synth"),
            ("strings", "Strings"),
            ("percussion", "Percussion"),
            ("brass", "Brass"),
            ("woodwinds", "Woodwinds"),
        ]
    )
    return HTMLResponse(
        html.replace("__PROJECT__", encoded).replace("__BRAND__", brand).replace("__ROLES__", roles)
    )
